using System.Text.RegularExpressions;

namespace TutorFlow.Core.Asistente;

internal sealed record BloqueDeTexto(string Texto, int InicioDeLaOracion);

internal enum TipoDeLinea
{
    Vacia,
    Separadora,
    Fila,
    Item,
    Encabezado,
    Texto
}

internal sealed record LineaPreparada(string Texto, TipoDeLinea Tipo);

internal static partial class BloquesDeRespuesta
{
    public static IReadOnlyList<BloqueDeTexto> De(string respuesta)
    {
        var estado = new EstadoDeBloques();
        return [.. SaltoDeLinea().Split(respuesta).Select(Preparar).SelectMany(estado.Procesar)];
    }

    internal static LineaPreparada Preparar(string linea)
    {
        var sinCita = linea.Trim().TrimStart('>').Trim();
        var eraNegrita = Negrita().IsMatch(sinCita);
        var texto = sinCita.Replace("**", string.Empty, StringComparison.Ordinal).Replace("__", string.Empty, StringComparison.Ordinal).Trim();
        return new LineaPreparada(texto, Clasificar(texto, eraNegrita));
    }

    private static TipoDeLinea Clasificar(string texto, bool eraNegrita)
    {
        if (texto.Length == 0)
        {
            return TipoDeLinea.Vacia;
        }

        return texto.StartsWith('|') ? DeTabla(texto) : ItemDeLista().IsMatch(texto) ? TipoDeLinea.Item : EsEncabezado(texto, eraNegrita) ? TipoDeLinea.Encabezado : TipoDeLinea.Texto;
    }

    private static TipoDeLinea DeTabla(string texto) =>
        Separador().IsMatch(texto) ? TipoDeLinea.Separadora : TipoDeLinea.Fila;

    private static bool EsEncabezado(string texto, bool eraNegrita) =>
        texto.EndsWith(':') || eraNegrita || texto.StartsWith('#');

    internal static IEnumerable<BloqueDeTexto> Oraciones(string linea, string contexto)
    {
        var prefijo = contexto.Length == 0 ? string.Empty : contexto + " ";
        return CorteDeOracion().Split(linea)
            .Where(oracion => !string.IsNullOrWhiteSpace(oracion))
            .Select(oracion => new BloqueDeTexto(prefijo + oracion, prefijo.Length));
    }

    [GeneratedRegex(@"\r?\n", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SaltoDeLinea();

    [GeneratedRegex(@"^(\*\*|__).+(\*\*|__):?$", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex Negrita();

    [GeneratedRegex(@"^[|\-:\s]+$", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex Separador();

    [GeneratedRegex(@"^(?:[-*•]|\d+[.)])\s", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex ItemDeLista();

    [GeneratedRegex(@"(?<=[.!?;])(?=\s|$)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CorteDeOracion();
}

internal sealed class EstadoDeBloques
{
    private string? _encabezado;
    private string? _textoPrevio;
    private string? _contextoDeLista;
    private string? _encabezadoDeColumnas;
    private bool _ultimaFueVacia;

    public IEnumerable<BloqueDeTexto> Procesar(LineaPreparada linea)
    {
        var bloques = linea.Tipo switch
        {
            TipoDeLinea.Vacia or TipoDeLinea.Separadora => [],
            TipoDeLinea.Fila => DeFila(linea),
            TipoDeLinea.Item => DeItem(linea),
            TipoDeLinea.Encabezado => DeEncabezado(linea),
            _ => DeTexto(linea)
        };
        _ultimaFueVacia = linea.Tipo == TipoDeLinea.Vacia || (linea.Tipo == TipoDeLinea.Separadora && _ultimaFueVacia);
        _encabezadoDeColumnas = linea.Tipo is TipoDeLinea.Fila or TipoDeLinea.Separadora ? _encabezadoDeColumnas : null;
        _textoPrevio = linea.Tipo == TipoDeLinea.Texto ? linea.Texto : null;
        return bloques;
    }

    private List<BloqueDeTexto> DeFila(LineaPreparada linea)
    {
        var contexto = _encabezadoDeColumnas is null ? string.Empty : $"{_encabezadoDeColumnas} {_encabezado}".Trim();
        _encabezadoDeColumnas ??= linea.Texto;
        return [.. BloquesDeRespuesta.Oraciones(linea.Texto, contexto)];
    }

    private List<BloqueDeTexto> DeItem(LineaPreparada linea)
    {
        _contextoDeLista = _textoPrevio ?? _contextoDeLista;
        return [.. BloquesDeRespuesta.Oraciones(linea.Texto, _encabezado ?? _contextoDeLista ?? string.Empty)];
    }

    private List<BloqueDeTexto> DeEncabezado(LineaPreparada linea)
    {
        _encabezado = linea.Texto;
        _contextoDeLista = null;
        return [.. BloquesDeRespuesta.Oraciones(linea.Texto, string.Empty)];
    }

    private List<BloqueDeTexto> DeTexto(LineaPreparada linea)
    {
        _encabezado = _ultimaFueVacia ? null : _encabezado;
        _contextoDeLista = null;
        return [.. BloquesDeRespuesta.Oraciones(linea.Texto, _encabezado ?? string.Empty)];
    }
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal static partial class ReferenciasEscritas
{
    internal const char Marca = '';
    private const string DocumentoDerogado = "reglamento_academico_2023.md";
    private const string LetrasDeNombre = @"[\p{L}\p{N}_-]";
    private const string Numero = @"\d+(?:\.\d+)*";
    private const string ReferenciaASeccion =
        @"(?<![\p{L}\p{N}])(?:secci[oó]n(?:es)?|art[ií]culos?|art\.?|§)\s*" + Numero + @"(?:\s*(?:,|y|e)\s*" + Numero + ")*";
    private const string ConectorDeReferencia =
        @"(?:(?<!" + LetrasDeNombre + @")(?:seg[uú]n|de\s+acuerdo\s+con|conforme\s+al?|ver|consulta|se\s+respaldan?\s+en|en|del?)(?:\s+(?:el|la|los|las))?"
        + @"|(?<!" + LetrasDeNombre + @")(?:el|la|los|las))\s+$";

    public static string Limpiar(string respuesta, IReadOnlyList<Cita> citas)
    {
        var marcada = AtribucionGenerica.Marcar(MarcarReferenciasInvalidas(respuesta, citas), citas);
        marcada = FraseFijaAnexada(marcada);
        return marcada.Contains(Marca, StringComparison.Ordinal) ? LimpiezaDeOraciones.Depurar(marcada) : respuesta;
    }

    public static bool TieneContenido(string texto) => PalabraDeLetras().IsMatch(texto) || CifraDeContenido().IsMatch(texto);

    private static string MarcarReferenciasInvalidas(string respuesta, IReadOnlyList<Cita> citas)
    {
        var invalidas = Unir(DocumentosEscritos.En(respuesta).Select(documento => Ampliar(respuesta, documento, citas)))
            .Where(rango => !rango.Valida)
            .Select(rango => rango with { Inicio = ConConector(respuesta, rango.Inicio) })
            .OrderByDescending(rango => rango.Inicio);
        var texto = respuesta;
        foreach (var rango in invalidas)
        {
            texto = string.Concat(texto.AsSpan(0, rango.Inicio), Marca.ToString(), texto.AsSpan(rango.Fin));
        }

        return texto;
    }

    private static RangoDeReferencia Ampliar(string texto, DocumentoEscrito documento, IReadOnlyList<Cita> citas)
    {
        var derecha = SeccionesALaDerecha().Match(texto, documento.Fin);
        var izquierda = SeccionALaIzquierda().Match(texto[..documento.Inicio]);
        var numeros = (izquierda.Success ? NumerosDe(izquierda.Groups["sec"].Value) : [])
            .Concat(derecha.Groups["sec"].Captures.SelectMany(captura => NumerosDe(captura.Value)))
            .ToList();
        var inicio = izquierda.Success ? izquierda.Index : documento.Inicio;
        return new RangoDeReferencia(inicio, derecha.Index + derecha.Length, EsValida(documento.Nombre, numeros, citas));
    }

    private static List<RangoDeReferencia> Unir(IEnumerable<RangoDeReferencia> rangos)
    {
        var unidos = new List<RangoDeReferencia>();
        foreach (var rango in rangos.OrderBy(rango => rango.Inicio))
        {
            unidos.AddRange(unidos.Count > 0 && rango.Inicio <= unidos[^1].Fin ? Fusionar(unidos, rango) : [rango]);
        }

        return unidos;
    }

    private static List<RangoDeReferencia> Fusionar(List<RangoDeReferencia> unidos, RangoDeReferencia rango)
    {
        var ultimo = unidos[^1];
        unidos.RemoveAt(unidos.Count - 1);
        return [new RangoDeReferencia(ultimo.Inicio, Math.Max(ultimo.Fin, rango.Fin), ultimo.Valida && rango.Valida)];
    }

    private static int ConConector(string texto, int inicio)
    {
        var conector = Conector().Match(texto[..inicio]);
        return conector.Success ? conector.Index : inicio;
    }

    private static bool EsValida(string documento, List<string> numeros, IReadOnlyList<Cita> citas) =>
        numeros.Count == 0
            ? string.Equals(documento, DocumentoDerogado, StringComparison.OrdinalIgnoreCase) || citas.Any(cita => MismoDocumento(cita, documento))
            : numeros.All(numero => citas.Any(cita => MismoDocumento(cita, documento) && NumeroDeCita(cita) == numero));

    private static bool MismoDocumento(Cita cita, string documento) =>
        documento.All(char.IsAscii) && string.Equals(cita.Documento, documento, StringComparison.OrdinalIgnoreCase);

    private static string? NumeroDeCita(Cita cita) => NumeroDeSeccion().Matches(cita.Seccion).LastOrDefault()?.Value;

    private static IEnumerable<string> NumerosDe(string seccion) => NumeroDeSeccion().Matches(seccion).Select(numero => numero.Value);

    private static string FraseFijaAnexada(string texto)
    {
        var sinFrase = Regex.Replace(texto, Regex.Escape(Textos.SinInformacion), Marca.ToString(), RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos));
        return TieneContenido(sinFrase.Replace(Marca, ' ')) ? sinFrase : texto;
    }

    private sealed record RangoDeReferencia(int Inicio, int Fin, bool Valida);

    [GeneratedRegex(@"\G(?:\s*[·,:-]\s*(?<sec>" + ReferenciaASeccion + "))*", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SeccionesALaDerecha();

    [GeneratedRegex(@"(?<sec>" + ReferenciaASeccion + @")\s+(?:de\s+la|del|de|en\s+el|en)\s+$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SeccionALaIzquierda();

    [GeneratedRegex(ConectorDeReferencia, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex Conector();

    [GeneratedRegex(@"\d+(?:\.\d+)*", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex NumeroDeSeccion();

    [GeneratedRegex(@"\p{L}{2,}", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraDeLetras();

    [GeneratedRegex(@"(?<![\d.])\d\.\d{1,2}(?!\d)|(?<![\d.])\d+(?:\.\d{1,2})?\s*%", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CifraDeContenido();
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static partial class LimpiezaDeOraciones
{
    private const int PalabrasMinimasPorOracion = 3;
    private const string EspacioEnBlanco = " ";

    private static readonly TimeSpan LimiteRegex = TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos);

    private static readonly (Regex Patron, string Reemplazo)[] ReglasDeSignos =
    [
        (new Regex(@"[\(\[][\s·,;:]*[\)\]]", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
        (new Regex(@" {2,}", RegexOptions.CultureInvariant, LimiteRegex), EspacioEnBlanco),
        (new Regex(@"(?<!\d) +(?=[.,;:!?)])|(?<=\d) +(?=[;:!?)]|[.,](?!\d))", RegexOptions.CultureInvariant, LimiteRegex), string.Empty),
        (new Regex(@"(?<!\.)\.\.(?!\.)", RegexOptions.CultureInvariant, LimiteRegex), "."),
        (new Regex(@"[,;:]\.", RegexOptions.CultureInvariant, LimiteRegex), "."),
        (new Regex(@",,", RegexOptions.CultureInvariant, LimiteRegex), ","),
        (new Regex(@"^[\s:,;·]+", RegexOptions.CultureInvariant, LimiteRegex), string.Empty)
    ];

    public static string Depurar(string marcada) =>
        string.Concat(CorteDeOracion().Split(marcada).Select(Oracion)).Trim();

    private static string Oracion(string oracion) =>
        oracion.Contains(ReferenciasEscritas.Marca, StringComparison.Ordinal) ? Depurada(oracion) : oracion;

    private static string Depurada(string marcada)
    {
        var texto = marcada.Replace(ReferenciasEscritas.Marca, ' ');
        if (TerminaEnAtribucionHuerfana(texto) || HuecoTrasPalabraIncompleta(marcada) || QuedaCorta(texto))
        {
            return string.Empty;
        }

        var margen = EspaciosIniciales().Match(texto).Value;
        var cola = EspaciosFinales().Match(texto).Value;
        var cuerpo = ReglasDeSignos.Aggregate(texto.Trim(), (actual, regla) => regla.Patron.Replace(actual, regla.Reemplazo)).Trim();
        return margen + Capitalizar(cuerpo, marcada) + cola;
    }

    private static bool TerminaEnAtribucionHuerfana(string texto) =>
        AtribucionHuerfana().IsMatch(PuntuacionFinal().Replace(texto, string.Empty));

    private static bool HuecoTrasPalabraIncompleta(string marcada) =>
        Enumerable.Range(0, marcada.Length)
            .Where(indice => marcada[indice] == ReferenciasEscritas.Marca)
            .Any(indice => PalabraIncompleta().IsMatch(NormalizadorTexto.Normalizar(marcada[..indice]).TrimEnd()));

    private static bool QuedaCorta(string texto) =>
        TerminaConPuntoFinal().IsMatch(texto.TrimEnd()) && PalabraOCifra().Count(texto) < PalabrasMinimasPorOracion;

    private static string Capitalizar(string cuerpo, string marcada)
    {
        var inicio = LetraTrasLaMarca().Match(marcada);
        return inicio.Success && cuerpo.Length > 0 && char.IsLower(cuerpo[0]) && cuerpo[0] == inicio.Groups["letra"].Value[0]
            ? char.ToUpperInvariant(cuerpo[0]) + cuerpo[1..]
            : cuerpo;
    }

    [GeneratedRegex(@"(?<=\n)|(?<=[.!?])(?=\s|$)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex CorteDeOracion();

    [GeneratedRegex(@"^\s*", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex EspaciosIniciales();

    [GeneratedRegex(@"\s*$", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex EspaciosFinales();

    [GeneratedRegex(@"[\s.,;:!?)\]]+$", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PuntuacionFinal();

    [GeneratedRegex(@"[.!?]\z", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex TerminaConPuntoFinal();

    [GeneratedRegex(@"[\p{L}\p{N}]+", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraOCifra();

    [GeneratedRegex(@"^[\s]*[\s]*(?<letra>\p{Ll})", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex LetraTrasLaMarca();

    [GeneratedRegex(
        @"(?<![\p{L}\p{N}])(?:a|al|con|de|del|en|por|segun|sobre|esta|estan|figuran?|aparecen?|respaldad[oa]s?|se\s+respaldan?"
        + @"|se\s+basan?|basad[oa]s?|se\s+encuentran?|provienen?|se\s+establecen?|establecid[oa]s?|se\s+indican?|consulta|ver)\z",
        RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PalabraIncompleta();

    [GeneratedRegex(
        @"(?<![\p{L}\p{N}])(?:a|al|con|de|del|en|por|según|segun|sobre|respaldad[oa]s?|se\s+respaldan?|se\s+basan?|basad[oa]s?|se\s+encuentran?"
        + @"|provienen?|se\s+establecen?|establecid[oa]s?|se\s+indican?|consulta|ver)\z",
        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
    private static partial Regex AtribucionHuerfana();
}

