using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal sealed record TramoDePersona(string PersonaId, IReadOnlyList<TokenTexto> Tokens);

internal sealed record PersonasDeBloque(IReadOnlyList<TramoDePersona> Tramos, bool Ambiguo)
{
    public static PersonasDeBloque Ninguna { get; } = new([], false);
}

internal static class TramosDePersonas
{
    private static readonly HashSet<string> PalabrasDelSujetoCoordinado = new(StringComparer.Ordinal) { "y", "e", "id" };

    public static PersonasDeBloque De(
        BloqueDeTexto bloque,
        Usuario usuario,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(bloque.Texto);
        if (usuario.Rol != Rol.Coordinador)
        {
            return new PersonasDeBloque([new TramoDePersona(usuario.Id, tokens)], false);
        }

        var menciones = DetectorTerceros.MencionesDeAutorizados(bloque.Texto, idsAutorizados, directorio);
        var enOracion = menciones.Where(mencion => mencion.Inicio >= bloque.InicioDeLaOracion).ToList();
        var delContexto = menciones.Where(mencion => mencion.Inicio < bloque.InicioDeLaOracion).Select(mencion => mencion.Id).Distinct().ToList();
        return enOracion.Count == 0 ? SoloDelContexto(delContexto, tokens) : new PersonasDeBloque(DeLaOracion(enOracion, delContexto, tokens), false);
    }

    private static PersonasDeBloque SoloDelContexto(List<string> delContexto, IReadOnlyList<TokenTexto> tokens) =>
        delContexto.Count switch
        {
            0 => PersonasDeBloque.Ninguna,
            1 => new PersonasDeBloque([new TramoDePersona(delContexto[0], tokens)], false),
            _ => new PersonasDeBloque([], true)
        };

    private static List<TramoDePersona> DeLaOracion(List<MencionDeAutorizado> menciones, List<string> delContexto, IReadOnlyList<TokenTexto> tokens)
    {
        var primeraDeCualquiera = menciones[0].Inicio;
        var tramos = menciones.GroupBy(mencion => mencion.Id)
            .Select(grupo => TramoDe(grupo.Key, grupo.First().Inicio, menciones, tokens, primeraDeCualquiera))
            .ToList();
        var coordinados = Coordinar(tramos, menciones);
        return [.. coordinados.Concat(delContexto.Where(id => coordinados.All(tramo => tramo.PersonaId != id)).Select(id => new TramoDePersona(id, tokens)))];
    }

    private static TramoDePersona TramoDe(
        string personaId,
        int inicio,
        IReadOnlyList<MencionDeAutorizado> menciones,
        IReadOnlyList<TokenTexto> tokens,
        int primeraDeCualquiera)
    {
        var fin = menciones
            .Where(mencion => mencion.Id != personaId && mencion.Inicio > inicio)
            .Select(mencion => mencion.Inicio)
            .DefaultIfEmpty(int.MaxValue)
            .Min();
        var delTramo = tokens.Where(token => token.Inicio < primeraDeCualquiera || (token.Inicio >= inicio && token.Inicio < fin));
        return new TramoDePersona(personaId, [.. delTramo]);
    }

    private static List<TramoDePersona> Coordinar(IReadOnlyList<TramoDePersona> tramos, IReadOnlyList<MencionDeAutorizado> menciones)
    {
        var coordinados = tramos.ToList();
        for (var indice = coordinados.Count - 2; indice >= 0; indice--)
        {
            coordinados[indice] = ComparteElPredicado(coordinados[indice], menciones)
                ? coordinados[indice] with { Tokens = [.. coordinados[indice].Tokens.Union(PropiosDe(coordinados[indice + 1], menciones)).OrderBy(token => token.Inicio)] }
                : coordinados[indice];
        }

        return coordinados;
    }

    private static IEnumerable<TokenTexto> PropiosDe(TramoDePersona siguiente, IReadOnlyList<MencionDeAutorizado> menciones) =>
        siguiente.Tokens.Where(token => !EnMencion(token, siguiente.PersonaId, menciones));

    private static bool ComparteElPredicado(TramoDePersona tramo, IReadOnlyList<MencionDeAutorizado> menciones)
    {
        var primera = menciones.First(mencion => mencion.Id == tramo.PersonaId).Inicio;
        return tramo.Tokens
            .Where(token => token.Inicio >= primera && !EnMencion(token, tramo.PersonaId, menciones))
            .All(token => PalabrasDelSujetoCoordinado.Contains(token.Valor));
    }

    private static bool EnMencion(TokenTexto token, string personaId, IReadOnlyList<MencionDeAutorizado> menciones) =>
        menciones.Any(mencion => mencion.Id == personaId && token.Inicio >= mencion.Inicio && token.Inicio < mencion.Fin);
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

public sealed record AsignaturaCatalogo(string Codigo, string Nombre);

internal sealed record AparicionDeAsignatura(string Clave, int Inicio, int Fin);

internal static class CatalogoAsignaturas
{
    public static IReadOnlyList<AsignaturaCatalogo> Vigente(IReadOnlyList<AsignaturaCatalogo> catalogo, DirectorioAcademico directorio) =>
        [.. catalogo.Where(asignatura => !EsIdDePersona(asignatura.Codigo, directorio))];

    public static bool EsIdDePersona(string codigo, DirectorioAcademico directorio) =>
        directorio.Estudiantes.Any(estudiante => estudiante.Id == codigo) || directorio.Coordinadores.Any(coordinador => coordinador.Id == codigo);

    public static IReadOnlyList<string> CodigosNombrados(
        string pregunta,
        IReadOnlyList<AsignaturaCatalogo> catalogo,
        IReadOnlyCollection<string> codigosDelDirectorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(pregunta);
        var porNombre = catalogo.Where(a => Aparece(tokens, a.Nombre)).Select(a => a.Codigo);
        var porCodigo = codigosDelDirectorio.Concat(catalogo.Select(a => a.Codigo)).Where(codigo => Aparece(tokens, codigo));
        return [.. porNombre.Concat(porCodigo).Select(AmbitoPersonal.Clave).Distinct(StringComparer.Ordinal)];
    }

    public static IReadOnlyList<AparicionDeAsignatura> Apariciones(
        IReadOnlyList<TokenTexto> tokens,
        IReadOnlyList<AsignaturaCatalogo> catalogo) =>
        [.. catalogo.SelectMany(asignatura => new[] { asignatura.Nombre, asignatura.Codigo }
            .Select(TokenizadorTexto.Valores)
            .Where(secuencia => secuencia.Count > 0)
            .SelectMany(secuencia => TokenizadorTexto.BuscarSecuencias(tokens, secuencia)
                .Select(inicio => new AparicionDeAsignatura(AmbitoPersonal.Clave(asignatura.Codigo), inicio, inicio + secuencia.Count - 1))))];

    private static bool Aparece(IReadOnlyList<TokenTexto> tokens, string texto)
    {
        var secuencia = TokenizadorTexto.Valores(texto);
        return secuencia.Count > 0 && TokenizadorTexto.BuscarSecuencia(tokens, secuencia) >= 0;
    }
}
using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace TutorFlow.Core.Autorizacion;

internal readonly record struct TokenTexto(string Valor, int Inicio, int Fin);

internal static partial class TokenizadorTexto
{
    private const int UnDigito = 1;
    private const int HastaDosDigitos = 2;
    private const int SinLimite = int.MaxValue;
    private static readonly Dictionary<string, string> NombreDelSimbolo = new() { ["≤"] = "<=", ["≥"] = ">=" };

    public static IReadOnlyList<TokenTexto> Tokenizar(string texto)
    {
        var acumulador = new AcumuladorTokens();
        var inicio = 0;
        foreach (var rune in texto.EnumerateRunes())
        {
            var fin = inicio + rune.Utf16SequenceLength;
            ProcesarRune(acumulador, rune, inicio, fin);
            inicio = fin;
        }

        acumulador.Cerrar();
        return acumulador.Tokens;
    }

    public static IReadOnlyList<TokenTexto> TokenizarConCifras(string texto)
    {
        var tokens = Tokenizar(texto);
        var resultado = new List<TokenTexto>();
        for (var indice = 0; indice < tokens.Count; indice++)
        {
            var esCifra = EsCifraDeNota(texto, tokens, indice);
            resultado.Add(esCifra
                ? new TokenTexto(tokens[indice].Valor + "." + tokens[indice + 1].Valor, tokens[indice].Inicio, tokens[indice + 1].Fin)
                : tokens[indice]);
            indice += esCifra ? 1 : 0;
        }

        return [.. resultado.Concat(Simbolos(texto)).OrderBy(token => token.Inicio)];
    }

    public static int BuscarSecuencia(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia) =>
        BuscarSecuencias(tokens, secuencia).DefaultIfEmpty(-1).First();

    public static IEnumerable<int> BuscarSecuencias(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia) =>
        Enumerable.Range(0, Math.Max(0, tokens.Count - secuencia.Count + 1))
            .Where(indice => CoincideEn(tokens, indice, secuencia));

    public static string Plegado(string texto) =>
        string.Concat(texto.EnumerateRunes().SelectMany(PlegadoCompatibilidad.De).Select(char.ToLowerInvariant));

    public static IReadOnlyList<string> Valores(string texto) =>
        Tokenizar(texto).Select(token => token.Valor).ToList();

    private static IEnumerable<TokenTexto> Simbolos(string texto) =>
        SimboloDeComparacion().Matches(texto)
            .Select(coincidencia => new TokenTexto(NombreDelSimbolo.GetValueOrDefault(coincidencia.Value, coincidencia.Value), coincidencia.Index, coincidencia.Index + coincidencia.Length));

    private static bool EsCifraDeNota(string texto, IReadOnlyList<TokenTexto> tokens, int indice) =>
        indice + 1 < tokens.Count
        && FormaDeCifra(texto, tokens[indice], tokens[indice + 1])
        && !ContinuaUnaCifra(texto, tokens, indice - 1, indice)
        && !ContinuaUnaCifra(texto, tokens, indice + 1, indice + 2);

