            _valor.Clear();
        }
    }

    [GeneratedRegex("<=|>=|[<>≤≥]", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SimboloDeComparacion();
