using System.Globalization;
using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static class EnterosDeAsistencia
{
    private const int PalabrasHastaLaPalabraClave = 3;

    private static readonly HashSet<string> PalabrasClave = new(StringComparer.Ordinal)
    {
        "falta", "faltas", "inasistencia", "inasistencias", "clase", "clases"
    };

    private static readonly HashSet<string> PalabrasQueExcluyen = new(StringComparer.Ordinal)
    {
        "corte", "cortes", "semana", "semanas", "nivel", "seccion", "secciones", "articulo", "articulos", "art"
    };

    private static readonly HashSet<string> Conectores = new(StringComparer.Ordinal) { "y", "e", "a" };

    public static HashSet<string> De(ResumenEstudiante resumen) =>
        resumen.Asignaturas
            .SelectMany(resultado => new int?[]
            {
                resultado.Asignatura.Asistencia.Inasistencias,
                resultado.Asignatura.Asistencia.ClasesProgramadas,
                resultado.FaltasPermitidas,
                resultado.FaltasRestantes
            })
            .OfType<int>()
            .Select(entero => entero.ToString(CultureInfo.InvariantCulture))
            .ToHashSet(StringComparer.Ordinal);

    public static IEnumerable<string> Candidatos(string texto, IReadOnlyList<TokenTexto> tokens) =>
        Enumerable.Range(0, tokens.Count)
            .Where(indice => EsEntero(tokens[indice]) && !EsPorcentaje(texto, tokens[indice]) && !ExcluidoPorLaPalabraPrevia(tokens, indice) && TienePalabraClaveCerca(tokens, indice))
            .Select(indice => tokens[indice].Valor);

    private static bool EsEntero(TokenTexto token) => token.Valor.All(char.IsAsciiDigit);

    private static bool EsPorcentaje(string texto, TokenTexto token) =>
        texto[token.Fin..].TrimStart().StartsWith('%');

    private static bool ExcluidoPorLaPalabraPrevia(IReadOnlyList<TokenTexto> tokens, int indice)
    {
        var anterior = indice - 1;
        while (anterior >= 0 && (EsEntero(tokens[anterior]) || Conectores.Contains(tokens[anterior].Valor)))
        {
            anterior--;
        }

        return anterior >= 0 && PalabrasQueExcluyen.Contains(tokens[anterior].Valor);
    }

    private static bool TienePalabraClaveCerca(IReadOnlyList<TokenTexto> tokens, int indice) =>
        Enumerable.Range(Math.Max(0, indice - PalabrasHastaLaPalabraClave), (2 * PalabrasHastaLaPalabraClave) + 1)
            .Where(posicion => posicion < tokens.Count)
            .Any(posicion => PalabrasClave.Contains(tokens[posicion].Valor));
}

using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

internal static class VozDeTu
{
    private const int PalabrasHastaElCampo = 2;

    private static readonly HashSet<string> Segunda = new(StringComparer.Ordinal) { "tu", "tus", "tienes", "te" };

    private static readonly HashSet<string> Campos = new(StringComparer.Ordinal)
    {
        "definitiva", "definitivas", "promedio", "falta", "faltas", "inasistencia", "inasistencias", "clase", "clases",
        "perdida", "perdidas", "aprobada", "aprobadas", "reprobada", "reprobadas", "prueba"
    };

    private static readonly HashSet<string> Referencias = new(StringComparer.Ordinal)
    {
        "programa", "programas", "estudiante", "estudiantes", "coordinador", "coordinadora"
    };

    public static bool Hay(IReadOnlyList<TokenTexto> tokens) =>
        Enumerable.Range(0, tokens.Count).Any(indice => Segunda.Contains(tokens[indice].Valor) && !EsReferencia(tokens, indice) && TieneCampoCerca(tokens, indice));

    private static bool EsReferencia(IReadOnlyList<TokenTexto> tokens, int indice) =>
        indice + 1 < tokens.Count && Referencias.Contains(tokens[indice + 1].Valor);

    private static bool TieneCampoCerca(IReadOnlyList<TokenTexto> tokens, int indice) =>
        Enumerable.Range(Math.Max(0, indice - PalabrasHastaElCampo), (2 * PalabrasHastaElCampo) + 1)
            .Where(posicion => posicion < tokens.Count && posicion != indice)
            .Any(posicion => Campos.Contains(tokens[posicion].Valor));
}

